//! Clip timing operations: trims and rate changes with source and action bounds.

use crate::edit_clip::clip_end;
use crate::edit_speed_profile::profile_factors;
use crate::model::{Clip, Project, Source};
use crate::model_words::rebase_words;
use crate::outcome::Outcome;
use crate::recipe_graphic::graphic_advanced;
use crate::source_window::source_advanced_through;
use crate::time::Ticks;

/// Speed range, `SPEED_MIN`–`SPEED_MAX` (spec §4.3, §11 #190). Three
/// readers: `set_speed` clamps to it, `rate_stretch` stays inside it, and
/// `Project::validate` refuses a clip outside it (spec §11 R6-10, amended by
/// #41). The app reads it through `rc_speed_limits` and never retypes it.
pub(crate) const SPEED_MIN: f64 = 0.1;
pub(crate) const SPEED_MAX: f64 = 1000.0;

/// The fastest a clip's audio still plays, in both pitch modes (spec §11
/// #190, the owner's decision of 2026-10-01). Above it the plan leaves the
/// clip's audio segment out (`evaluate.rs`); the video still runs to
/// `SPEED_MAX`. Chosen with a margin below a measured stall: an h264
/// export's loudness pass never finishes for a keep-pitch clip that starts
/// its audio track from ×15, nor in either mode from about ×20; ×12 and ×14
/// finish. B52a's mixer limits (×24 spectral, ×32 varispeed) hold only for
/// the mixer and an audio-only export, and are not the product's ceiling.
pub(crate) const AUDIO_SPEED_MAX: f64 = 12.0;

/// Every number about speed, as `rc_speed_limits` publishes it:
/// `{"min":0.1,"max":1000.0,"audio_max":12.0}`.
pub(crate) fn speed_limits() -> serde_json::Value {
    serde_json::json!({
        "min": SPEED_MIN,
        "max": SPEED_MAX,
        "audio_max": AUDIO_SPEED_MAX,
    })
}

impl Project {
    /// Moves the clip's start edge to `to`, advancing the source in point
    /// by `(to - start) × speed` so the frame under the edge does not move
    /// (spec §6).
    ///
    /// Clamped to the source bound — `to ≥ start - in/speed` snapped UP to
    /// a frame, `source_window.rs`'s `earliest_start_on_grid` (spec §11,
    /// D4-5) — and to leaving at least one frame of clip. Actions are
    /// deliberately left alone: clip-relative, rebasing would drop or bake
    /// whatever fell off the front, which is lossy and makes trimming back
    /// out not an identity. On a RAMPED clip the actions keep their clip
    /// time too, so `in` advances by round(S(Δ)) moving in and at the base
    /// rate moving out, and the edge is held where the clip still fits its
    /// media (`front_edge_held`, spec §11 SR-18 (c)): what plays after the
    /// new start can change. `text.words` are the opposite, on purpose
    /// (spec §11, W-3): a word is anchored to speech that stays where it is
    /// on the timeline, so every word is rebased by the trim's delta and a
    /// word trimmed off the front keeps its (negative) time. A graphic's
    /// `in` advances by the same delta (road map 10's G-9), with no speed
    /// and no head bound, never below 0.
    ///
    /// Without `alone`, a linked partner whose start is this clip's is
    /// trimmed to the same `to` after it, by its own clamps; with it, the
    /// clip moves alone — the J-cut (spec §11 AU-93, `carried_edge`).
    pub fn trim_start(&self, clip: u32, to: Ticks, alone: bool) -> Result<Outcome, String> {
        self.carried_edge(
            clip,
            alone,
            |target, partner| partner.start == target.start,
            |project, id| project.trim_start_one(id, to),
        )
    }

    fn trim_start_one(&self, clip: u32, to: Ticks) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        let end = clip_end(&target);
        let latest = end.saturating_sub(self.frame());
        let mut to = self.snapped(to).min(latest).max(0);

        if let Some(earliest) = self.earliest_start_on_grid(&target) {
            to = to.max(earliest.max(0));
        }
        // A ramped clip's edge is held where the clip still fits its media
        // (spec §11 SR-18 (c)); a constant clip's is `to` as clamped.
        let to = self.front_edge_held(&target, to);
        // The two clamps can cross when the source has almost nothing left
        // in front: then there is no legal new start, so nothing happens.
        if to > latest || to == target.start {
            return Ok(Outcome::Identity);
        }

        let delta = to.saturating_sub(target.start);
        let mut moved = target.clone();
        moved.source = source_advanced_through(&target, delta);
        moved.start = to;
        moved.duration = end.saturating_sub(to);
        moved.graphic = graphic_advanced(target.graphic.as_ref(), delta);
        if let Some(text) = moved.text.as_mut() {
            rebase_words(text, delta);
        }
        self.commit_replacements(vec![moved])
    }

    /// Moves the clip's end edge to `to`, clamped to the source's remaining
    /// length (media sources) and to at least one frame of clip (spec §6).
    /// The source in point and the actions are untouched. The bound is
    /// `source_window.rs`'s `latest_end_on_grid`, measured at this clip's
    /// OWN start: the last frame at or before the end of the file, and
    /// never the one past it (spec §11, #22 and D4-2). A ramped clip's bound
    /// reads its map on past the end (S∞, spec §11 SR-18 (a)). A graphic's
    /// `length` is untouched: null follows the new end, a number stays (G-9).
    /// `alone` is `trim_start`'s: without it a linked partner ending where
    /// this clip ends follows; with it, the L-cut (spec §11 AU-93).
    pub fn trim_end(&self, clip: u32, to: Ticks, alone: bool) -> Result<Outcome, String> {
        self.carried_edge(
            clip,
            alone,
            |target, partner| clip_end(partner) == clip_end(target),
            |project, id| project.trim_end_one(id, to),
        )
    }

    fn trim_end_one(&self, clip: u32, to: Ticks) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        let earliest = target.start.saturating_add(self.frame());
        let mut to = self.snapped(to).max(earliest);
        if let Some(latest) = self.latest_end_on_grid(&target) {
            to = to.min(latest);
        }
        if to < earliest || to == clip_end(&target) {
            return Ok(Outcome::Identity);
        }

        let mut moved = target.clone();
        moved.duration = to.saturating_sub(target.start);
        self.commit_replacements(vec![moved])
    }

    /// Drags the clip's end edge to `to_end` by changing its SPEED, not the
    /// source range it shows: `speed = source_len / (to_end - start)`
    /// (spec §6). Media sources only.
    ///
    /// An IDENTITY when the new length is under a frame or the resulting rate
    /// falls outside `SPEED_MIN`–`SPEED_MAX`; refused only when the placement
    /// breaks the overlap rule. Actions keep their clip-relative fraction.
    ///
    /// On a RAMPED clip the whole rate profile scales by f = D ÷ (to_end −
    /// start) through `scaled_profile`, so the ramp keeps its shape and its
    /// window; an f that would take any rate the clip names past the limits
    /// (`profile_factors`) changes nothing (spec §11 SR-19 (a), (b)).
    /// Refused on a linked clip (spec §11 AU-94).
    pub fn rate_stretch(&self, clip: u32, to_end: Ticks) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        if !matches!(target.source, Source::Media { .. }) {
            return Err(format!("clip {clip} is not a media clip"));
        }
        let to_end = self.snapped(to_end);
        let duration = to_end.saturating_sub(target.start);
        if duration < self.frame() {
            return Ok(Outcome::Identity);
        }
        if let Some((low, high)) = profile_factors(&target) {
            let factor = target.duration as f64 / duration as f64;
            if !factor.is_finite() || !(low..=high).contains(&factor) {
                return Ok(Outcome::Identity);
            }
            let moved = self.scaled_profile(&target, factor, duration);
            return self.commit_rate(&target, moved);
        }
        let rate = self.content_length_in_source(&target) as f64 / duration as f64;
        if !rate.is_finite() || !(SPEED_MIN..=SPEED_MAX).contains(&rate) {
            return Ok(Outcome::Identity);
        }

        let mut moved = target.clone();
        moved.speed = rate;
        moved.duration = duration;
        self.rescale_actions(&mut moved.actions, target.duration, duration);
        self.commit_rate(&target, moved)
    }

    /// A rate edit's commit: refused on a linked clip whose rate it changes
    /// (spec §11 AU-94), else placed as any replacement is.
    fn commit_rate(&self, before: &Clip, moved: Clip) -> Result<Outcome, String> {
        if let Some(why) = self.linked_rate_refusal(before, &moved) {
            return Ok(Outcome::Refused(why));
        }
        self.commit_replacements(vec![moved])
    }

    /// Sets the clip's playback rate: `duration = source_len / rate` held
    /// to what the file holds AT THAT RATE (`duration_at_speed`, spec §11
    /// D4-3), actions keeping their clip-relative fraction (spec §6). Media
    /// sources only; `keep_pitch`, when given, sets the time-pitch flag.
    ///
    /// Takes a `rate` or a `duration`, exactly one (spec §11 #190). A
    /// duration is the Fit arm: snapped to the grid, held to a frame, and
    /// turned into the rate that plays the clip's content in it; the current
    /// duration keeps the current rate, so it makes no phantom step.
    ///
    /// Either rate is clamped to `SPEED_MIN`–`SPEED_MAX` rather than
    /// refused, because a slider or an MCP call that asks for more wants the
    /// fastest thing available. `Err` for both or neither, a non-media clip,
    /// a rate that is not a positive finite number or a duration that is not
    /// positive; refuses on an overlap-rule violation.
    ///
    /// On a RAMPED clip the whole rate profile scales by one factor f — the
    /// clamped rate over the base, or D ÷ d — clamped so no rate the clip
    /// names passes a limit (`profile_factors`): the ramp keeps its shape
    /// and its window, and its base may stop short of the rate asked; when
    /// f does not clamp, the base is the clamped rate itself. The
    /// new duration is d, or snapped(round(D ÷ f)) when f clamped or the
    /// rate arm set it, held through `scaled_profile` (spec §11 SR-19 (a),
    /// (b)). An f of 1 changes nothing but `keep_pitch`. A linked clip's
    /// rate is refused (spec §11 AU-94); `keep_pitch` alone is not a rate.
    pub fn set_speed(
        &self,
        clip: u32,
        rate: Option<f64>,
        duration: Option<Ticks>,
        keep_pitch: Option<bool>,
    ) -> Result<Outcome, String> {
        match (rate, duration) {
            (Some(_), Some(_)) => {
                return Err(format!(
                    "set_speed takes a rate or a duration, not both (clip {clip})"
                ))
            }
            (None, None) => {
                return Err(format!(
                    "set_speed takes a rate or a duration (clip {clip})"
                ))
            }
            _ => {}
        }
        let target = self.require_clip(clip)?.clone();
        if !matches!(target.source, Source::Media { .. }) {
            return Err(format!("clip {clip} is not a media clip"));
        }
        if let Some(rate) = rate {
            if !(rate.is_finite() && rate > 0.0) {
                return Err(format!("speed must be a positive number, not {rate}"));
            }
        }
        if let Some(duration) = duration {
            if duration <= 0 {
                return Err(format!("duration must be positive, not {duration}"));
            }
        }
        if let Some((low, high)) = profile_factors(&target) {
            let frame = self.frame();
            let (asked, fitted) = match (rate, duration) {
                (Some(rate), _) => (rate.clamp(SPEED_MIN, SPEED_MAX) / target.speed, None),
                (None, Some(duration)) => {
                    let d = self.snapped(duration).max(frame);
                    if d == target.duration {
                        (1.0, None)
                    } else {
                        (target.duration as f64 / d as f64, Some(d))
                    }
                }
                (None, None) => (1.0, None),
            };
            let factor = asked.clamp(low, high);
            let length = match fitted {
                Some(d) if factor == asked => d,
                _ => {
                    let scaled = (target.duration as f64 / factor).round();
                    if scaled.is_finite() {
                        self.snapped(scaled as Ticks).max(frame)
                    } else {
                        target.duration
                    }
                }
            };
            let mut moved = self.scaled_profile(&target, factor, length);
            // An unclamped rate arm writes the rate asked itself: `speed ×
            // (rate ÷ speed)` can miss it by an ULP (spec §11 SR-19 (a)).
            if let (Some(rate), true) = (rate, factor == asked) {
                moved.speed = rate.clamp(SPEED_MIN, SPEED_MAX);
            }
            if let (Some(keep), Some(audio)) = (keep_pitch, moved.audio.as_mut()) {
                audio.keep_pitch = keep;
            }
            return self.commit_rate(&target, moved);
        }
        let rate = match (rate, duration) {
            (Some(rate), _) => rate,
            (None, Some(duration)) => {
                let d = self.snapped(duration).max(self.frame());
                if d == target.duration {
                    target.speed
                } else {
                    self.content_length_in_source(&target) as f64 / d as f64
                }
            }
            (None, None) => target.speed,
        };
        let rate = rate.clamp(SPEED_MIN, SPEED_MAX);

        let mut moved = target.clone();
        moved.speed = rate;
        moved.duration = self.duration_at_speed(&target, rate);
        self.rescale_actions(&mut moved.actions, target.duration, moved.duration);
        if let (Some(keep), Some(audio)) = (keep_pitch, moved.audio.as_mut()) {
            audio.keep_pitch = keep;
        }
        self.commit_rate(&target, moved)
    }
}

use std::collections::HashMap;

use serde_json::Value;

use crate::edit_clip::clip_end;
use crate::model::{Clip, Curve, Project, Source};
use crate::outcome::Outcome;
use crate::speed_map::end_speed;
use crate::time::Ticks;

/// A linked SOUND half: linked, its picture off — the half Detach Audio
/// made, and the half whose edge a J- or L-cut drags alone.
fn is_linked_sound(clip: &Clip) -> bool {
    clip.linked.is_some() && !clip.enabled.video
}

/// AU-94's sentence: `clip`'s rate may not change while it is linked to
/// `partner`. Written once for `linked_rate_refusal` and `retime_range`
/// (spec §11 CU-90 (b)).
pub(crate) fn linked_rate_sentence(clip: u32, partner: u32) -> String {
    format!(
        "clip {clip} is linked to clip {partner}: Attach Audio before changing its speed or \
         direction"
    )
}

/// Every `(clip, named)` in one container whose link is one-sided: the
/// clip it names is absent, is itself, or does not name it back. Read off
/// the container as it stands, so a mutual pair is never on the list and
/// clearing what is cannot break one.
fn one_sided(clips: &[Clip]) -> Vec<(u32, u32)> {
    if clips.iter().all(|c| c.linked.is_none()) {
        return Vec::new();
    }
    let named: HashMap<u32, Option<u32>> = clips.iter().map(|c| (c.id, c.linked)).collect();
    clips
        .iter()
        .filter_map(|clip| {
            let partner = clip.linked?;
            let back = named.get(&partner).copied().flatten();
    mutating func update(time: Ticks, row: Int, snapper: TimelineSnapper) {
        let raw = time - grabTime
        let resolved = snapper.resolve(spanStart + raw)
        delta = resolved.time - spanStart
        guide = resolved.guide
        // A clip can never start before zero (§6 clamps it); keeping the
        // preview honest about that stops the group sliding while the core
        // refuses to follow.
        if spanStart + delta < 0 { delta = -spanStart }
        self.row = row
        didMove = true
    }
}

// MARK: - Trim

/// Dragging a clip edge (spec §6 `trim_start` / `trim_end`), or with ⌥ a
/// rate stretch of the end.
///
/// **Pitfall:** `rate_stretch` only takes `to_end`, so ⌥ on the START edge
/// has nothing to express — it trims like a bare drag rather than pretending
/// to stretch and silently doing something else.
struct TrimSession {
    let clip: UInt32
    let edge: TimelineEdge
    let stretch: Bool
    /// The grabbed clip is a linked SOUND half, so its edge moves without
    /// its picture's — the J- or L-cut (spec §11 AU-93). A picture's edge
    /// carries to a sound whose edge coincides.
    let alone: Bool
    let originalStart: Ticks
    let originalEnd: Ticks
    /// One frame of the document's grid: the minimum a clip may keep.
    let frame: Ticks

    var time: Ticks
    var guide: Ticks?
    var didMove = false

    /// True when ⌥ actually changes the op.
    var isRateStretch: Bool { stretch && edge == .end }

    var op: ReelOp {
        switch edge {
        case .start:
            return .trimStart(clip: clip, to: min(time, originalEnd - frame), alone: alone)
        case .end:
            let to = max(time, originalStart + frame)
            return isRateStretch
                ? .rateStretch(clip: clip, toEnd: to)
                : .trimEnd(clip: clip, to: to, alone: alone)
        }
    }

    mutating func update(time: Ticks, snapper: TimelineSnapper) {
        let resolved = snapper.resolve(time)
        // Clamped here as well as in the core: the preview must not show an
        // inverted bar for the ticks the core is busy refusing.
        switch edge {
        case .start:
            self.time = max(0, min(resolved.time, originalEnd - frame))
        case .end:
            self.time = max(resolved.time, originalStart + frame)
        }
        guide = resolved.guide
        didMove = true
            row: layout.row(forTrackIndex: index))
        onLiveBegin?()
    }

    private func probeTrack(_ ops: [ReelOp], existing: Set<UInt32>) -> UInt32? {
        guard let probed = onProbe?(ops) else { return nil }
        return probed.tracks.first { !existing.contains($0.id) }?.id
    }

    private func beginTrim(_ id: UInt32, edge: TimelineEdge, flags: NSEvent.ModifierFlags) {
        guard let clip = snapshot.clip(id),
              let index = snapshot.trackIndex(of: clip.track),
              !snapshot.tracks[index].locked
        else { return }
        let frame = max(snapshot.canvas.fps.frameDuration, 1)
        dragSnapper = makeSnapper(excluding: [id], suppressed: flags.contains(.command))
        trim = TrimSession(
            clip: id, edge: edge,
            stretch: flags.contains(.option) && clip.source.hasSourceBound,
            alone: clip.isLinkedSound,
            originalStart: clip.start, originalEnd: clip.end, frame: frame,
            time: edge == .start ? clip.start : clip.end)
        onLiveBegin?()
    }

    /// The destination track id for the row a drag is over, or nil to leave
    /// every clip on its own track. Read from the gesture's base handle.
    private func destination(for session: ClipDragSession) -> UInt32? {
        guard let base = dragBase, session.row != session.anchorRow,
              (0..<base.tracks.count).contains(session.row)
        else { return nil }
        return base.tracks[base.tracks.count - 1 - session.row].id
    }

    /// ⌥-click a track header: every clip on it (spec §9). Here rather than
    /// in `EditorViewController+Edge.swift` only because `selection` is
    /// `private(set)` — it is the same view-state channel `selectClip` and
    /// the marquee use, and registers no undo step.
    private func selectClipsOnTrack(_ track: UInt32) {
        let ids = Set(snapshot.clips.filter { $0.track == track }.map { $0.id })
        guard selection != ids else { return }
        selection = ids
        onSelectionChanged?(selection)
    }

    /// A press on empty timeline space — a lane's gap, or above or below
    /// the lanes: a bare press clears the selection and ⇧ keeps it, then the
    /// band starts (`RangeSession`). One body for `.lane` and `.outside`, so
    /// the two places a band can start cannot drift apart. The clear is
    /// posted at the press rather than at the first drag, which is what
    /// makes a bare CLICK on empty space deselect.
    /// Source time of the clip's first frame; 0 for kinds with no source
    /// bound (§5.2 — `still`, `image`, `text`, `shape` may take any length).
    var sourceIn: Ticks {
        switch self {
        case .media(_, let sourceIn, _): return sourceIn
        case .still(_, let at): return at
        case .image, .text, .shape, .graphic, .nest, .adjustment: return 0
        }
    }

    /// Only `media` clips are limited by their source's length, and only
    /// they accept `set_speed` / `rate_stretch` (§6).
    var hasSourceBound: Bool {
        if case .media = self { return true }
        return false
    }
}

/// One clip on one track. The bar the timeline draws and the layer the
/// compositor composites.
struct ClipSnapshot: Codable, Equatable, Identifiable {
    let id: UInt32
    let track: UInt32
    /// Project time of the clip's first frame.
    let start: Ticks
    let duration: Ticks
    let source: ClipSource
    let enabled: EnabledFlags
    /// Playback rate; `media` sources only (§6 `set_speed`).
    let speed: Double
    let video: VideoProps?
                audioPane.compressorSection(), audioPane.mixSection(),
                // Last in the clip's chain, so last here (spec §11 AU-26).
                audioPane.limiterSection(),
            ]
        case .clip:
            if binding.isSingle, let clip = binding.primary {
                sections.append(timingSection(clip.id))
            } else if videoPane.allMedia {
                // The half of Timing a MULTI-clip selection can still answer
                // for: Reverse is a per-clip op that fans out happily, where
                // In, Out and Duration genuinely need one clip.
                sections.append(reverseTimingSection())
            }
            if videoPane.allMedia {
                sections.append(videoPane.speedSection())
            }
            if binding.isSingle, let clip = binding.primary,
               videoPane.overlap(before: clip) != nil {
                sections.append(videoPane.transitionSection(clip.id))
            }
            if hasPixels {
                sections.append(videoPane.motionSection())
            }
        }
        // A tab that would open as a column of shut headers opens its first
        // section with no stored preference instead. `expandByDefault` defers
            to: url, options: options,
            graphics: GraphicRegistry.shared.snapshot(for: document.recipeKey))
        // Adding to a queue shows the queue: the job has no sheet of its own,
        // so this window is the only thing that says it exists.
        ExportQueueWindowController.shared.show()
    }

    // MARK: - Speed

    /// Clip ▸ Speed…. Only `media` clips can take `set_speed` (spec §6 makes
    /// it an error, not a refusal, on any other kind), so the sheet is opened
    /// on that subset and refused outright when the subset is empty.
    func presentSpeedSheet() {
        let clips = selectedClips.filter { $0.source.hasSourceBound }
        guard let document = document, !clips.isEmpty else {
            NSSound.beep()
            return
        }
        presentAsSheet(SpeedSheetController(document: document, clips: clips.map { $0.id }))
    }

    /// Clip ▸ Speed Ramp… (spec §11 SR-24): the speed ramp presets on the ONE
    /// selected media clip. Its validator is the same test.
    @objc func showSpeedRampSheet(_ sender: Any?) { presentSpeedRampSheet() }

    /// Opens the sheet on the selected clip, over the in/out range when it
    /// lies inside the clip and the whole clip otherwise
    /// (`SpeedRampSheetController.span(of:range:)`).
    func presentSpeedRampSheet() {
        let clips = selectedClips
        guard let document = document, clips.count == 1, let clip = clips.first,
            clip.source.hasSourceBound
        else {
            NSSound.beep()
            return
        }
/// The near-unity band, inclusive, in which keep pitch plays `time_domain`.
pub(crate) const PITCH_TIME_DOMAIN_MIN: f64 = 0.98;
pub(crate) const PITCH_TIME_DOMAIN_MAX: f64 = 1.02;

/// The band, inclusive, in which keep pitch plays `off` (spec §11 SY-39); ×1 excluded.
pub(crate) const PITCH_VARISPEED_MIN: f64 = 0.999;
pub(crate) const PITCH_VARISPEED_MAX: f64 = 1.001;

impl Pitch {
    pub(crate) fn of(keep_pitch: bool, speed: f64) -> Pitch {
        let varispeed =
            speed != 1.0 && (PITCH_VARISPEED_MIN..=PITCH_VARISPEED_MAX).contains(&speed);
        if !keep_pitch || varispeed {
            Pitch::Off
        } else if speed != 1.0 && (PITCH_TIME_DOMAIN_MIN..=PITCH_TIME_DOMAIN_MAX).contains(&speed) {
            Pitch::TimeDomain
        } else {
            Pitch::Spectral
        }
    }

    pub(crate) fn name(self) -> &'static str {
        match self {
            Pitch::Spectral => "spectral",
            Pitch::TimeDomain => "time_domain",
            Pitch::Off => "off",
        }
    }
}

// ---- the A/B assignment --------------------------------------------------

/// One clip's contribution to the composition: a source range placed at a
/// timeline range. `duration != source_duration` is Swift's signal to
/// follow the insert with `scaleTimeRange` (spec §7.2).
///
/// A ramped clip's ONE audio segment carries `ramp`, the map its rendered
/// sound follows (spec §11 SR-6, SR-10), and so does a constant media
/// clip's time-scaled Keep pitch off audio segment (SR-28,
/// [`Segment::with_constant_render`]); every other segment has none. An
/// audio segment carries `track_pans`, the pans of the tracks its voice plays
/// through ([`Segment::with_track_pans`], spec §11 AU-104), empty when none.
#[derive(Debug, Clone)]
