    static func title(for rate: Double) -> String {
        String(format: rate < 1 ? "%.2f×" : "%g×", rate)
    }

    // MARK: - Values

    /// The rate the controls describe, always inside §6's clamp.
    private var rate: Double {
        SpeedRateControls.clamp(rateField.doubleValue)
    }

    private var keepPitch: Bool { pitchCheckbox.state == .on }

    /// The ops Apply sends — one `set_speed` per clip, in the selection's own
    /// order — so what the readout asks about and what Apply writes are one
    /// list and cannot drift. `applyClicked` calls it.
    static func ops(for clips: [UInt32], rate: Double, keepPitch: Bool) -> [ReelOp] {
        clips.map { .setSpeed(clip: $0, rate: rate, keepPitch: keepPitch) }
    }

    /// A clip whose transition a trial makes play (#109), or makes longer or
    /// shorter (#184), and that transition's length after the trial.
    struct TransitionChange: Equatable {
        enum Change: Equatable { case gains, grows, shrinks }
        let clip: UInt32
        let kind: TransitionKind
        let change: Change
        /// The overlap with its predecessor after the trial.
        let duration: Ticks
    }

    /// The project once the sheet's ops have run — the ONE `applying` every
    /// line of the readout is read off. A refusal still answers the project
    /// with the refused clips as they were.
    static func trial(
        of clips: [UInt32], rate: Double, keepPitch: Bool, in project: ReelProject
    ) -> ProjectSnapshot {
        let ops = Self.ops(for: clips, rate: rate, keepPitch: keepPitch)
        return ((try? project.applying(ops)).project ?? project).snapshot
    }

    /// What the selection measures now, and what it measures once those ops
    /// have run — the two numbers the readout prints, both read off a project.
    ///
    /// `after` is summed from the handle the ops make, not from arithmetic
    /// here, which is the whole of the type doc's claim. A clip the core
    /// refused is absent from nothing — it is still in the applied snapshot,
    /// at the length it had — so a refusal reads as "no change" for that clip
    /// and the rest of the selection still counts.
    static func lengths(
        of clips: [UInt32], rate: Double, keepPitch: Bool, in project: ReelProject
    ) -> (before: Ticks, after: Ticks) {
        lengths(
            of: clips, before: project.snapshot,
            after: trial(of: clips, rate: rate, keepPitch: keepPitch, in: project))
    }

    static func lengths(
        of clips: [UInt32], before snapshot: ProjectSnapshot, after applied: ProjectSnapshot
    ) -> (before: Ticks, after: Ticks) {
        var before: Ticks = 0
        var after: Ticks = 0
        for id in clips {
            guard let clip = snapshot.clip(id), clip.speed > 0 else { continue }
            before += clip.duration
            after += applied.clip(id)?.duration ?? clip.duration
        }
        return (before, after)
    }

    /// Every clip, on a track holding one of `clips`, whose transition plays
    /// in `after` and either did not in `before` (`.gains` — a minted cross
    /// dissolve, or a transition set earlier that an overlap now reaches) or
    /// did at a smaller or larger overlap (`.grows`, `.shrinks`). A transition
    /// plays when the clip has one and overlaps its predecessor
    /// (`VideoPane.overlap(before:)`'s idiom). One that plays in both at the
    /// same overlap is absent. Ordered by start, then id.
    static func transitionChanges(
        of clips: [UInt32], before: ProjectSnapshot, after: ProjectSnapshot
    ) -> [TransitionChange] {
        func overlap(_ id: UInt32, in snapshot: ProjectSnapshot) -> Ticks {
            guard let clip = snapshot.clip(id) else { return 0 }
            let earlier = snapshot.clips(onTrack: clip.track).filter { $0.start < clip.start }
            guard let previous = earlier.last else { return 0 }
            return previous.end - clip.start
        }
        func effective(_ id: UInt32, in snapshot: ProjectSnapshot) -> Bool {
            snapshot.clip(id)?.transitionIn != nil && overlap(id, in: snapshot) > 0
        }
        let tracks = Set(clips.compactMap { before.clip($0)?.track })
        var changes: [(start: Ticks, change: TransitionChange)] = []
        for clip in after.clips where tracks.contains(clip.track) {
            let id = clip.id
            let had = effective(id, in: before)
            guard effective(id, in: after), let kind = clip.transitionIn?.kind else { continue }
            let now = overlap(id, in: after)
            let was = overlap(id, in: before)
            guard !had || now != was else { continue }
            let change: TransitionChange.Change = !had ? .gains : now > was ? .grows : .shrinks
            changes.append(
                (clip.start, TransitionChange(clip: id, kind: kind, change: change, duration: now)))
        }
        return changes.sorted { ($0.start, $0.change.clip) < ($1.start, $1.change.clip) }
            .map(\.change)
    }

    /// "clip 7 gains a 0.67 s cross dissolve", "clip 7's cross dissolve grows
    /// to 1.50 s", "clip 7's cross dissolve shrinks to 0.67 s".
    static func changeLine(_ change: TransitionChange) -> String {
        let seconds = String(format: "%.2f", ReelTime.seconds(change.duration))
        let kind = change.kind.displayName.lowercased()
        switch change.change {
        case .gains: return "clip \(change.clip) gains a \(seconds) s \(kind)"
        case .grows: return "clip \(change.clip)'s \(kind) grows to \(seconds) s"
        case .shrinks: return "clip \(change.clip)'s \(kind) shrinks to \(seconds) s"
        }
    }

    /// The readout's last line when a selected clip ramps its speed: Apply
    /// sets the base rate and scales the ramp with it (rule L, spec §11
    /// SR-19 (a), SR-21 (f)).
    static let rampLine =
        "Each speed ramp keeps its shape: the rates it names scale with the base rate."

    /// "3 clips · 00:00:12:00 → 00:00:06:00", then one `changeLine` per clip
    /// whose transition the trial makes play, grow or shrink — every line
    /// read off one trial handle — then `rampLine` when a selected clip is
    /// ramped (the core's `sourceMap`).
    static func readout(
        of clips: [UInt32], rate: Double, keepPitch: Bool, in project: ReelProject
    ) -> String {
        let before = project.snapshot
        let after = trial(of: clips, rate: rate, keepPitch: keepPitch, in: project)
        let (from, to) = lengths(of: clips, before: before, after: after)
        let fps = before.canvas.fps
        let count = clips.count == 1 ? "1 clip" : "\(clips.count) clips"
        let summary =
            count + " · " + ReelTime.format(from, fps: fps, frames: true) + " → "
            + ReelTime.format(to, fps: fps, frames: true)
        let changes = transitionChanges(of: clips, before: before, after: after)
        let ramp = clips.contains { project.sourceMap($0)?.ramped == true } ? [rampLine] : []
        return ([summary] + changes.map(changeLine) + ramp).joined(separator: "\n")
    }

    private func syncReadout() {
        guard let project = document?.editedProject else {
            durationLabel.stringValue = ""
            return
        }
        durationLabel.stringValue = Self.readout(
            of: clips, rate: rate, keepPitch: keepPitch, in: project)
    }

    // MARK: - Controls

    @objc private func presetChosen(_ sender: Any?) {
        guard let preset = SpeedRateControls.preset(of: presetPopup) else { return }
        rateField.doubleValue = preset
        // The pull-down always shows its own title, so put it back.
        presetPopup.selectItem(at: 0)
        syncReadout()
    }

    @objc private func pitchChanged(_ sender: Any?) {
        syncReadout()
    }

    func controlTextDidEndEditing(_ obj: Notification) {
        rateField.doubleValue = rate
        syncReadout()
    }

    // MARK: - Commit

    @objc private func cancelClicked(_ sender: Any?) {
        dismiss(self)
    }

    /// One `set_speed` per clip, committed as ONE undo step. A rate that is
    /// already what every clip has is not an edit — the core would return
    /// identity and `applyEdit` would beep at a dialog the user just
    /// confirmed, which reads as a refusal rather than as "nothing to do".
    ///
    /// A rate that takes a clip with sound above the audio ceiling asks first
    /// (`SpeedAudioDrop`, #212), on this sheet's own window: Set Speed closes
    /// the sheet and applies, Cancel leaves the sheet up with nothing applied.
    @objc private func applyClicked(_ sender: Any?) {
        let rate = self.rate
        let keepPitch = self.keepPitch
        guard ratesDiffer || rate != originalRate || keepPitch != originalKeepPitch else {
            dismiss(self)
            return
        }
        guard let document = self.document, !clips.isEmpty else {
            dismiss(self)
            return
        }
        SpeedAudioDrop.commit(
            "Set Speed", Self.ops(for: clips, rate: rate, keepPitch: keepPitch), to: document,
            asking: view.window, before: { [weak self] in if let self { self.dismiss(self) } })
    }
}

import AppKit

/// The question a person is asked before a speed change takes a clip with
/// sound above the core's audio ceiling (#212, spec §11 #190's "The
/// question"), and the sentence an agent reads instead.
///
/// **A crossing is read off the core's answer, never predicted.** The ops are
/// applied to the immutable handle (the trial the Speed sheet's readout
/// already runs, spec §11 D4-6) and the two snapshots are compared: a clip
/// that plays at or below `audio_max` before and above it after, with its
/// audio enabled and media that has sound. No rate is computed here (D2-1),
/// and no Swift file types the ceiling — it is `ReelSpeed.limits.audioMax`.
///
/// A clip that is new in the answer (a split's half, a duplicate, a detach)
/// never counts, and one already above the ceiling is not asked about again.
/// A `retime_range` (Clip ▸ Retime Range…, spec §11 CU-90 (c)) is read on a
/// BASELINE instead of the project: the project with `split` at its `from`
/// and then its `to` applied, so a half the retime takes past the ceiling is
/// already in the "before" under the id the core will mint, and counts.
/// A clip's rate here is its PEAK (`peakSpeed`): a speed ramp (spec §11
/// SR-10) leaves the audio out when any rate it names is above the
/// ceiling, as the core's plan does (SR-19 (d)).
/// Nothing here is a refusal: Set Speed applies the edit exactly as it would
/// have been applied without the question.
enum SpeedAudioDrop {
    /// A clip the edit takes above the ceiling. `name` is the after
    /// snapshot's `name(of:)`; `speed` is the clip's NEW peak rate as the
    /// core answered it.
    struct Clip: Equatable {
        let id: UInt32
        let name: String
        let speed: Double
    }

    /// True when any op is one that can change a speed: `set_speed`,
    /// `rate_stretch`, or a `set_action_end` whose patch names `speed` — the
    /// Speed section's Rate inside an action (spec §11 SR-21 (e)) — or an
    /// `add_speed_ramp`, Clip ▸ Speed Ramp… (SR-24 (e)), or a `retime_range`,
    /// Clip ▸ Retime Range… (CU-90 (c)).
    /// `set_action` and `remove_action` cannot raise the rate a clip names.
    static func mayCross(_ ops: [ReelOp]) -> Bool {
        ops.contains {
            $0.name == "set_speed" || $0.name == "rate_stretch"
                || $0.name == "add_speed_ramp" || $0.name == "retime_range"
                || ($0.name == "set_action_end"
                    && ($0.args["patch"] as? [String: Any])?["speed"] != nil)
        }
    }

    /// Every clip, on the timeline or in a nest, whose audio `after` leaves
    /// out and `before` did not. Sorted by id.
    static func crossing(
        from before: ProjectSnapshot, to after: ProjectSnapshot,
        limits: SpeedLimits = ReelSpeed.limits
    ) -> [Clip] {
        var earlier: [UInt32: Double] = [:]
        for clip in before.clips + before.nests.flatMap(\.clips) {
            earlier[clip.id] = peakSpeed(of: clip, limits: limits)
        }
        var found: [Clip] = []
        for clip in after.clips + after.nests.flatMap(\.clips) {
            let peak = peakSpeed(of: clip, limits: limits)
            guard clip.source.hasSourceBound, clip.enabled.audio,
                after.media(for: clip)?.hasAudio == true,
                peak > limits.audioMax,
                let was = earlier[clip.id], was <= limits.audioMax
            else { continue }
            found.append(Clip(id: clip.id, name: after.name(of: clip), speed: peak))
        }
        return found.sorted { $0.id < $1.id }
    }

    /// The greatest rate a clip names: its speed, or any action's end
    /// rate (spec §11 SR-10, SR-19 (d)), never computed. As the core's plan reads it,
    /// only a `media` clip ramps, and an end rate is clamped to the speed
    /// limits (a hand-written one may lie outside them).
    static func peakSpeed(
        of clip: ClipSnapshot, limits: SpeedLimits = ReelSpeed.limits
    ) -> Double {
        guard clip.source.hasSourceBound else { return clip.speed }
        return clip.actions.compactMap(\.end.speed)
            .filter(\.isFinite)
            .map { Swift.min(Swift.max($0, limits.min), limits.max) }
            .reduce(clip.speed, Swift.max)
    }

    /// The crossing `ops` would make on `project`: [] unless the core answers
    /// `.applied` (an identity, a refusal and a throw all change nothing).
    /// Read on `baseline(for:on:)`, which is `project` itself unless an op is
    /// a `retime_range`.
    static func crossing(
        applying ops: [ReelOp], to project: ReelProject,
        limits: SpeedLimits = ReelSpeed.limits
    ) -> [Clip] {
        let base = baseline(for: ops, on: project)
        guard case .applied(let after)? = try? base.applying(ops) else { return [] }
        return crossing(from: base.snapshot, to: after.snapshot, limits: limits)
    }

    /// `project` with `split` (every unlocked clip, as `split_under_playhead`
    /// cuts) at each `retime_range` op's `from` and then its `to`, in order,
    /// on the op's own scope — the cuts the core makes first, so the halves
    /// carry the ids it mints (CU-90 (c)). `project` itself when nothing
    /// applies. No rate is computed here (D2-1).
    static func baseline(for ops: [ReelOp], on project: ReelProject) -> ReelProject {
        var base = project
        for op in ops where op.name == "retime_range" {
            for key in ["from", "to"] {
                guard let at = (op.args[key] as? NSNumber)?.int64Value else { continue }
                var split = ReelOp.split(clips: nil, at: at)
                split.scope = op.scope
                if case .applied(let next)? = try? base.applying(split) { base = next }
            }
        }
        return base
    }

    /// "×12": the ceiling as the inspector's note spells it.
    static func ceiling(_ limits: SpeedLimits) -> String {
        rate(limits.audioMax)
    }

    private static func rate(_ value: Double) -> String {
        "×" + String(format: "%g", value)
    }

    /// The alert's message and detail.
    static func question(
        _ clips: [Clip], limits: SpeedLimits = ReelSpeed.limits
    ) -> (message: String, detail: String) {
        let ceiling = Self.ceiling(limits)
        guard clips.count > 1 else {
            let name = clips.first?.name ?? ""
            let speed = clips.first.map { rate($0.speed) } ?? ceiling
            return (
                "“\(name)” will be silent at \(speed).",
                "Frame Job leaves a clip’s audio out above \(ceiling). The picture still plays."
            )
        }
        let speeds = Set(clips.map { rate($0.speed) })
        let at = speeds.count == 1 ? (speeds.first ?? "") : "their new speeds"
        return (
            "\(clips.count) clips will be silent at \(at).",
            "Frame Job leaves a clip’s audio out above \(ceiling). The pictures still play."
        )
    }

    /// The sentence an agent's answer carries in place of the question.
    static func note(_ clips: [Clip], limits: SpeedLimits = ReelSpeed.limits) -> String {
        let ceiling = Self.ceiling(limits)
        guard clips.count > 1 else {
            let id = clips.first.map { String($0.id) } ?? ""
            let name = clips.first?.name ?? ""
            return "Clip \(id) (“\(name)”) now plays above \(ceiling), so its audio is left "
                + "out: it is silent in the preview and the export."
        }
        let ids = clips.map { String($0.id) }
        let listed = ids.dropLast().joined(separator: ", ") + " and " + (ids.last ?? "")
        return "Clips \(listed) now play above \(ceiling), so their audio is left out: they "
            + "are silent in the preview and the export."
    }

    /// The keys an op tool's answer gains: none when nothing crossed.
    static func answerFields(
        from before: ProjectSnapshot, to after: ProjectSnapshot,
        limits: SpeedLimits = ReelSpeed.limits
    ) -> [String: Any] {
        answerFields(crossing(from: before, to: after, limits: limits), limits: limits)
    }

    /// The same keys for a crossing already read — `retime_range`'s tool
    /// reads its own on the baseline before the edit (CU-90 (e)).
    static func answerFields(
        _ clips: [Clip], limits: SpeedLimits = ReelSpeed.limits
    ) -> [String: Any] {
        guard !clips.isEmpty else { return [:] }
        return [
            "audio_left_out": clips.map { Int($0.id) },
            "audio_note": note(clips, limits: limits),
        ]
    }

    /// The question, as an alert sheet on `window`: "Set Speed" (the
    /// default) or "Cancel". `answer(true)` only for Set Speed. A sheet's
    /// completion is not an AppKit event, so a caller commits through
    /// `performGroupedEdit` (app/CLAUDE.md's undo pitfall).
    static func ask(
        _ clips: [Clip], on window: NSWindow, limits: SpeedLimits = ReelSpeed.limits,
        answer: @escaping (Bool) -> Void
    ) {
        let text = question(clips, limits: limits)
        let alert = NSAlert()
        alert.messageText = text.message
        alert.informativeText = text.detail
        alert.addButton(withTitle: "Set Speed")
        alert.addButton(withTitle: "Cancel")
        alert.beginSheetModal(for: window) { response in
            answer(response == .alertFirstButtonReturn)
        }
    }

    /// The one door a person's speed edit goes through — the Speed, Speed
    /// Ramp and Retime Range sheets' Apply and the inspector's commit. The captions the edit
    /// re-times ride in the same step, under its name "and Re-time Captions"
    /// (`CaptionRetime`, spec §11 SR-27). An edit that takes no
    /// clip with sound above the ceiling runs `before` and is applied at once;
    /// one that does asks on `window` first: Set Speed runs `before` and
    /// applies, Cancel runs `declined`. With no window to ask on it beeps and
    /// runs `declined`, applying nothing. A document that changed while the
    /// question was up is planned again on Set Speed (SR-27 (h)), not asked
    /// again.
    static func commit(
        _ name: String, _ ops: [ReelOp], to document: ProjectDocument, asking window: NSWindow?,
        before: @escaping () -> Void = {}, declined: @escaping () -> Void = {}
    ) {
        let (rawName, rawOps) = (name, ops)
        let handle = document.project
        let (name, ops) = CaptionRetime.withRetime(rawName, rawOps, on: document.editedProject)
        let crossing = mayCross(ops) ? Self.crossing(applying: ops, to: document.editedProject) : []
        guard !crossing.isEmpty else {
            before()
            document.applyEdit(name, ops)
            return
        }
        guard let window else {
            NSSound.beep()
            declined()
            return
        }
        ask(crossing, on: window) { [weak document] confirmed in
            guard confirmed else {
                declined()
                return
            }
            before()
            guard let document else { return }
            let step =
                document.project === handle
                ? (name: name, ops: ops)
                : CaptionRetime.withRetime(rawName, rawOps, on: document.editedProject)
            // A sheet's completion is not an AppKit event: the grouped entry
            // point is mandatory here (app/CLAUDE.md's undo pitfall).
            document.performGroupedEdit(step.name, step.ops)
        }
    }
}
  Typing a rate, or choosing one from the quick-pick menu, sets the action's
  end rate. This turns any action into a Speed action.
- The section header shows no **Reset** while an action is selected. To end
  the action at ×1, type 1 or choose 1 from Rate's quick-pick menu.
- The section header's **Clear** button (shown when the action sets a rate), the row's × on hover, and the row's
  right-click **Remove from action** take the rate out of the action.
- **Keep pitch** still sets the clip's own setting, at the clip's own rate.
- **Fit to** is the clip's alone and cannot be set inside an action. Its row
  is marked ⊘.

### Changing the speed of a ramped clip

**Clip ▸ Speed…**, the Speed section's Rate with no action selected, Fit to
and the ⌥ rate stretch all scale a ramped clip's **whole** ramp by one
factor: the clip's own rate, every end rate and the length of every Speed
action. The ramp keeps its shape. For Speed…, Rate and Fit to, if scaling
would push any rate in the ramp past ×0.1 or ×1000, the scaling stops at that
limit, so the clip's rate can end up short of the rate you asked for. A ⌥
rate stretch that would do so does nothing.

Trims, slips, rolls, splits, freeze frames and transitions also follow the
ramp, so each cut or held frame is the frame the ramp actually plays at that
moment. **Edit ▸ Paste Attributes** never copies a speed or a ramp.
**Detach Audio** gives the separate audio clip the same ramp.

- **Splitting inside a Speed action** keeps the picture continuous at the
  cut, with no repeated or skipped frame. With an Ease Out or Ease In Out
  curve the rate can jump at the cut. With an Ease In or Ease In Out curve
  the second half can end on a different source frame.
- **An action past the clip's end.** After a trim, or after the ramp is
  scaled, a Speed action can lie partly or wholly past the clip's end. You
  can still re-curve it, move it earlier or shorten it; only a change that
  takes it further past the end is refused. Its end rate still counts for
  the ×12 rule, even though that part never plays.
- **Transcripts and captions.** Transcribing a ramped clip places each word
  where the ramp plays it. Captions and word captions already on the timeline
  follow a later change to the ramp, as below.

### Captions follow a speed change

When you change the speed of a clip with sound, or add, move, resize, edit or
remove a Speed action on it, the captions over that clip move with its speech
in the same undo step. The step is named after the edit with "and Re-time
Captions" added, such as **Set Speed and Re-time Captions**; one undo puts the
captions back too. A drag moves them when you let go of the mouse.

- **Which captions.** Text clips on a track named "Captions" or "Captions N"
  that holds only text clips and is not locked, each lying wholly inside the
  clip you edited. A caption that runs past either edge of the clip, and
  anything on another track, is left where it is.
- **Speech the clip no longer plays.** A caption whose speech the clip no
  longer reaches is removed. A word caption page that is only partly reached
  keeps the words that still play, and its text is cut to match.
- **Newly revealed speech.** When a speed-up or a ramp makes the clip play
  further into its file, the new part gets no captions. Generate Captions
  again to caption it ([Captions](captions.md)).
- **Neighbours.** A moved caption is cut back where it would run into a
  caption that did not move. One that would start inside such a caption, or
  would end up shorter than a frame, is removed.

### When a ramp is refused

A ramp may never play past the end of the clip's media file. An edit that
would do so is refused, and the reason names what would fit:

- setting an end rate too high names **the largest end rate that fits**, or,
  if no rate down to ×0.1 fits, the latest clip end that would fit at ×0.1
- moving, resizing or removing a Speed action, or clearing its rate, names
  **the latest clip end that fits**
- a Speed Ramp… preset names **the largest rate that fits**

Speed Ramp… is also refused when:

- the span runs past the clip's end
- the span overlaps an action already on the clip, including one inside a
  Dip's or Burst's hold
- a Dip or Burst span is shorter than two frames
- the rate is on the wrong side of the starting rate (for example, a Ramp Up
  to a rate that is not faster)

A refusal changes nothing. The inspector shows the reason at its foot, and
the Speed Ramp… sheet shows it in its readout.

### Rendered audio

Two kinds of clip have their sound rendered into a separate file in the
background, saved in the project package: a clip with a speed ramp, and a
clip at a constant speed other than ×1 with Keep pitch off. Renders run one
at a time, and a new one starts after each edit that changes the clip's
timing: a ramp, its rate, a trim or a split. Each render covers the whole
clip's sound. Undo and redo render again too, because the file from before
the edit is not kept, so the clip is briefly silent after an undo as well.
How long the silence lasts grows with the clip's length and rate: well under
a second for a 10 s clip, and a few seconds for a minute of ×4.

- **Keep pitch off:** the sound glides smoothly up and down in pitch with the
  rate, like tape, and stays in step with the picture. At a constant speed it
  plays at that speed's tape pitch, sample-exact.
- **Keep pitch on:** the sound keeps its own pitch as the speed changes.
  After a steep slow-down (for example ×2 → ×0.5) it can run up to about
  22 ms behind the picture.

While a clip's sound is still rendering, that clip plays silent in the
preview. An export waits for every render it needs (its progress reads
"Preparing…" during the wait) and never writes that sound silent. If a render
fails, the export fails with "Clip N's retimed audio could not be
rendered: …". A failed render is not tried again while Frame Job stays open:
the clip stays silent and exports that need it keep failing until you change
the clip's timing (which starts a new render) or quit and reopen Frame Job.

## Retime a range
124:- **When the pauses are noisy** (their median loudness less than 45 dB under the voice): **voice isolation** at 80 % with noise reduction off, or, on a clip isolation can't serve (a speed change, a ramp or a freeze frame), **noise reduction** at 50 %. And the **gate**, opening 10 dB above the pauses' median peak, held between −40 and −6 dB from the clip's loudness. With quiet pauses, isolation, noise reduction and the gate are turned off. With under half a second of pause there is nothing to measure, so they're left as they are.
172:- **−3 dB**: starts slowly and gathers speed; halfway through it is far quieter. Good for a fade out that should feel long.
215:- **The timeline shows it.** A clip that ducks by speech has a thin yellow line across its waveform: high where the others play at full level, low where they're ducked. It follows the clip's speed, reverse and speed ramps.
233:| Status | Read-only: "Rendering…", "Ready", "Plays without it at this speed", "Waits for the reversed copy", or "Not rendered:" and the reason. With several clips selected it reads "—". | — | Off |
241:Isolation plays only on a clip at normal speed. A clip with a speed change, a speed ramp or a freeze frame plays without it, and the Status says so. A reversed clip is isolated once its reversed copy is ready.
251:| Voice | **Pitch** shifts the voice up or down without changing its speed; **High** and **Deep** shift it up 5 or down 5 semitones and brighten or warm it; **Robot** makes it metallic and buzzing. |
269:The effect plays only on a clip at normal speed, as Voice Isolation does. A reverb or an echo stops at the end of the clip; it doesn't ring on into the next one.
